package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** The user reminding the claim. */
public class ValidateRemind {
    public void validate(@RequestBody RemindRequest request, Out<ChangedBy> changedBy) throws BadRequestException {
        changedBy.set(ChangedBy.of(request == null ? null : request.by()));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.access.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Reminds an OPEN or PENDING claim on the sheet's today; any other status, or a second reminder that day, is refused.
 * A reminder at least the sheet's escalation gap after the claim's previous one escalates it, once ever.
 */
public class ApplyRemind {
    public void apply(@Val Claim claim, ClaimRepository repository, SheetRepository sheets, SettingRepository settings,
            Out<RemindEscalation> escalation) throws BadRequestException {
        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
            throw new BadRequestException("Only an OPEN or PENDING claim is reminded; this one is " + claim.getStatus());
        }
        LocalDate today = sheets.today(claim.getSheetId());
        if (today.equals(claim.getRemindedOn())) {
            throw new BadRequestException("The claim was already reminded on " + today);
        }
        LocalDate previous = claim.getRemindedOn();
        if (!repository.remind(claim, today)) {
            throw new BadRequestException("The claim was changed by someone else; reload the sheet");
        }
        Integer gap = settings.escalateAfter(claim.getSheetId());
        boolean escalate = gap != null && previous != null && !previous.plusDays(gap).isAfter(today)
                && repository.escalate(claim);
        escalation.set(new RemindEscalation(escalate));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Val;

/** REMIND, naming the claim; then ESCALATE, naming it, when the reminder escalated it. */
public class RecordClaimReminded {
    public void record(@Val Claim claim, @Val ChangedBy by, @Val RemindEscalation escalation, PersonRepository people,
            Audit audit) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        String name = person == null ? "" : person.getName();
        audit.record(ClaimAudit.line("REMIND", claim, by, name));
        if (escalation != null && escalation.escalated()) {
            audit.record(ClaimAudit.line("ESCALATE", claim, by, name));
        }
    }
